const lum=h=>{const n=parseInt(h.slice(1),16);return(.299*(n>>16)+.587*(n>>8&255)+.114*(n&255))/255};
function applyTh(){const r=document.documentElement,on=Object.keys(TH).length;if(on)r.dataset.theme='light';else delete r.dataset.theme;['bg','card','brand','pill','pink','red','ink'].forEach(k=>TH[k]?r.style.setProperty('--'+k,TH[k]):r.style.removeProperty('--'+k));TH.pill?r.style.setProperty('--pillt',lum(TH.pill)>.55?'#2a1c15':'#fff'):r.style.removeProperty('--pillt');TH.brand?r.style.setProperty('--brandt',lum(TH.brand)>.6?'#2a1c15':'#fff'):r.style.removeProperty('--brandt')}
