async function dl(name,data){try{const c=window.claude,d=c&&c.use?await c.use('downloads'):null;if(d){await d.save({filename:name,data});toast('บันทึกไฟล์แล้ว');return}}catch(e){if(e&&e.code==='declined')return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'text/plain;charset=utf-8'}));a.download=name;document.body.appendChild(a);a.click();a.remove();toast('ดาวน์โหลดแล้ว')}
