function expAll(){const d={};IMPK.forEach(k=>{d[k]=({pr:P,px:PX,bn:BNR,ds:DS,tg:TG,qa:QA,ft:FT,nt:NT,info:INFO,wl:WL,th:TH,open:OPEN,gr:GR,cp:CP,bl:BL,ln:LN,py:PY,dc:DC,rm:RM,u:U,mb:MB,pf:PF,cs:CS,oh:OH})[k]});dl('jindevinesia-backup-'+tday()+'.json',JSON.stringify({v:1,at:new Date().toISOString(),data:d}))}
