const admX=()=>`<div class="pg"><b>ส่งออกข้อมูล</b><p style="color:var(--mut);margin:6px 0 12px">ไฟล์ CSV เปิดได้ด้วย Excel / Numbers / Google Sheets</p><button class="bt" style="width:100%;margin-bottom:10px" onclick="expCust()">ส่งออกข้อมูลลูกค้า + ยอดผ่อน (CSV)</button><small style="color:var(--mut)">ชื่อ ที่อยู่ เบอร์โทร รายละเอียดสินค้าที่ซื้อ ราคาเต็ม ยอดเต็ม ยอดที่จ่ายมาแล้ว คงเหลือ % งวด วันครบกำหนด และขาดผ่อนกี่วัน</small><button class="bt" style="width:100%;margin:14px 0 10px" onclick="expOrd()">ส่งออกออเดอร์ (CSV)</button><small style="color:var(--mut)">ออเดอร์ทุกรายการ ชื่อผู้สั่ง ที่อยู่จัดส่ง สินค้า บริการ ราคา ส่วนลด สถานะ</small><h2>สำรองข้อมูล</h2><button class="bt" style="width:100%;margin-bottom:10px" onclick="expAll()">สำรองข้อมูลทั้งหมด (JSON)</button><label>นำเข้าไฟล์สำรอง (จะเขียนทับข้อมูลปัจจุบัน)</label><input type="file" accept=".json,application/json" onchange="impAll(this.files[0])"></div>`;
const ovl=()=>{const R=[];names().forEach(n=>mb(n).items.forEach((x,i)=>{const d=dueI(x);if(d)R.push({n,i,x,d})}));return R.sort((a,b)=>b.d.d-a.d.d)};
const rmTxt=r=>RM.split('{NAME}').join((PF[r.n]||{}).first||r.n).split('{SHOP}').join(WL.name).split('{DEVICE}').join(r.x.n||'').split('{CODE}').join(r.x.cc||r.x.code||'-').split('{DUE}').join(dth(r.x.dd)).split('{DAYS}').join(r.d.d);
function cpR(i){cpy(rmTxt(ovl()[i]))}
const admV=()=>{const A=ovl(),late=A.filter(r=>r.d.late),soon=A.filter(r=>!r.d.late&&r.d.d>=-3),row=r=>{const f=PF[r.n]||{};return`<div class="bx" style="margin:8px 0"><div class="rw"><b>${r.n}${f.first?' · '+f.first+' '+(f.last||''):''}</b><span class="stb" style="${r.d.late?(r.d.G&&r.d.d>r.d.G?'background:#b03a3a;color:#fff':'background:#fbe0e0;color:#b03a3a'):''}">${r.d.late?'ขาด '+r.d.d+' วัน':'อีก '+(-r.d.d)+' วัน'}</span></div><small style="color:var(--mut)">${f.tel||'ไม่มีเบอร์'} · ${SV[kf(r.x)].n} · ${r.x.n||''}${r.x.cc?' · '+r.x.cc:''}<br>ค้าง ${fm(Math.max(0,(+r.x.t||0)-(+r.x.p||0)))} · ${r.d.t}</small><br><button class="stb" onclick="cpR(${A.indexOf(r)})">คัดลอกข้อความทวง</button></div>`};return`<div class="pg"><b>คนขาดผ่อน (${late.length})</b>${late.map(row).join('')||'<p style="color:var(--mut)">ไม่มีคนขาดผ่อน 🎉</p>'}<b style="display:block;margin-top:16px">ใกล้ครบกำหนด ภายใน 3 วัน (${soon.length})</b>${soon.map(row).join('')||'<p style="color:var(--mut)">ไม่มี</p>'}<label>ข้อความทวง (ใช้ {NAME} {SHOP} {DEVICE} {CODE} {DUE} {DAYS})</label><textarea class="ta" onchange="RM=this.value;W('rm',RM);toast('บันทึกแล้ว')">${esc(RM)}</textarea></div>`};
const memRows=()=>{const q=(S.mq||'').toLowerCase().trim(),ks=names().filter(n=>{if(!q)return true;const f=PF[n]||{};return [n,f.first,f.last,f.nick,f.tel,f.addr,...mb(n).items.map(x=>(x.cc||'')+' '+(x.code||'')+' '+(x.n||''))].join(' ').toLowerCase().includes(q)});return ks.map(n=>{const f=PF[n]||{},I=mb(n).items,t=I.reduce((a,x)=>a+(+x.t||0),0),p=I.reduce((a,x)=>a+(+x.p||0),0);return`<div class="bx" style="margin:0 0 10px;cursor:pointer" onclick="S.mv='${n}';render()"><div class="rw"><b>${n}${I.some(x=>(dueI(x)||{}).late)?' <span class="stb" style="background:#fbe0e0;color:#b03a3a">ขาดผ่อน</span>':''}</b><span>›</span></div><small style="color:var(--mut)">${f.first||''} ${f.last||''} · ${f.tel||'ยังไม่มีเบอร์'}<br>ออเดอร์ ${OH.filter(o=>o.u===n).length} · ผ่อน ${I.length} เครื่อง${I.some(x=>x.cc)?' · รหัส '+I.map(x=>x.cc).filter(Boolean).join(', '):''}${I.length?` · ${pct(t,p)}% (${fm(p)}/${fm(t)})`:''}</small></div>`}).join('')||'<p style="color:var(--mut)">ไม่พบสมาชิก</p>'};
function mlist(){const e=$('#ml');if(e)e.innerHTML=memRows()}
const admDC=()=>`<div class="pg"><b>โค้ดส่วนลด (ลูกค้ากรอกตอนสรุปใบเสร็จ)</b>${DC.map((d,i)=>`<div class="rw" style="align-items:center"><span><b>${d.c}</b> · ลด ${d.t==='pct'?d.v+'%':fm(d.v)}${d.min?' · ขั้นต่ำ '+fm(d.min):''}</span><button class="lk" onclick="DC.splice(${i},1);W('dc',DC);render(true)">ลบ</button></div>`).join('')||'<small style="color:var(--mut)">ยังไม่มีโค้ด</small>'}<div style="display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:6px;margin-top:10px"><input id="dc_c" placeholder="โค้ด" autocapitalize="characters"><select id="dc_t"><option value="baht">฿ บาท</option><option value="pct">%</option></select><input id="dc_v" placeholder="มูลค่า" inputmode="numeric"></div><input id="dc_m" placeholder="ยอดขั้นต่ำ (ไม่ใส่ก็ได้)" inputmode="numeric" style="margin-top:6px"><button class="bt" style="width:100%;margin-top:10px" onclick="addDC()">เพิ่มโค้ดส่วนลด</button></div>`;
