async function outAll(){try{await FB.signOut()}catch(e){}await loadUser(null);go('welcome')}
function go(v){clearInterval(tm);if(v==='admin'&&!ADM)v='pin';S.v=v;scrollTo(0,0);render()}
V.pin=()=>`<div class="ag ${WL.abg?'im':''}" ${WL.abg?`style="background:url(${WL.abg}) center/cover"`:''}><i class="b1"></i><i class="b2"></i><div class="gl"><button onclick="go('me')" style="font-size:13px">‹ กลับ</button><h2 style="color:#3a2a20;font-size:30px;font-weight:500;margin:14px 0 2px">แอดมิน</h2><div style="font-size:14px">เข้าสู่ระบบด้วยอีเมลแอดมิน</div><label>อีเมล</label><input id="ae" type="email" autocapitalize="off" autocorrect="off" value="${FB.ADMIN_EMAIL}"><label>รหัสผ่าน</label><input id="pn" type="password" autocomplete="current-password"><button class="gb" onclick="chkP()">เข้าสู่ระบบ</button></div></div>`;
async function addM(){const D=s=>s.replace(/[\u0e50-\u0e59]/g,c=>c.charCodeAt(0)-3664).replace(/\s/g,''),n=$('#am_n').value.trim(),a=D($('#am_d').value),b=D($('#am_m').value),c=D($('#am_y').value),pw=a.length===8&&!b&&!c?a:a.padStart(2,'0')+b.padStart(2,'0')+c;if(!n||!/^\d{8}$/.test(pw))return toast('กรอกชื่อและวันเกิดให้ครบ 8 หลัก');if(names().some(x=>x.toLowerCase()===n.toLowerCase()))return toast('ชื่อนี้มีอยู่แล้ว');try{const uid=await FB.createUser(await mail(n),pw);await FB.setMember(uid,{name:n,createdAt:Date.now(),by:'admin'});U[n]=uid;PF[n]=pick({});MB[n]={items:[]};LASTP.pf[n]=JSON.stringify(PF[n]);LASTP.mb[n]=JSON.stringify(MB[n]);toast('เพิ่มสมาชิกแล้ว');S.mv=n;render()}catch(e){toast(errMsg(e))}}
async function delMN(n){const uid=U[n];try{if(uid){await FB.delMember(uid);await FB.delBal(uid)}delete U[n];delete MB[n];delete PF[n];delete CS[n];S.mv=null;render();toast('ลบสมาชิกแล้ว (ถ้าจะใช้ชื่อเดิมสมัครใหม่ ต้องลบผู้ใช้ในหน้า Firebase › Authentication ด้วย)')}catch(e){toast(errMsg(e))}}
function doOrder(){if(!me){toast('กรุณาเข้าสู่ระบบก่อนสั่งซื้อ');return go('auth')}const nm=(($('#rc_n')||{}).value||'').trim();if(!nm)return toast('กรอกชื่อผู้สั่งซื้อ');const it=cart.map(c=>({p:pd(c.id),c})).filter(x=>x.p&&!isO(x.p)).map(({p,c})=>rit(p,c));if(!it.length)return toast('ไม่มีสินค้าที่สั่งได้');const sum=it.reduce((a,x)=>a+x.d,0),dis=dcc(sum),o={_id:FB.newId(),id:'JV'+Date.now().toString(36).slice(-6).toUpperCase(),uid:FB.user().uid,ts:Date.now(),st:'รอยืนยัน',u:me,nm,t:new Date().toLocaleDateString('th-TH'),it,disc:dis,net:sum-(dis?dis.a:0)};OH.unshift(o);W('oh',OH);cart=cart.filter(c=>{const p=pd(c.id);return !p||isO(p)});W('cart',cart);S.dc='';S.rd=o;S.rb='cart';render()}
